type ReminderMailInput = {
  to: string;
  subject: string;
  html: string;
};

function createTransport() {
  const host = process.env.SMTP_HOST;
  const port = process.env.SMTP_PORT ? Number(process.env.SMTP_PORT) : 587;
  const user = process.env.SMTP_USER;
  const pass = process.env.SMTP_PASS;

  if (!host || !user || !pass) return null;

  return nodemailer.createTransport({
    host,
    port,
    secure: process.env.SMTP_SECURE === "true" || port === 465,
    auth: { user, pass },
  });
}

export async function sendReminderEmail({ to, subject, html }: ReminderMailInput) {
  const from = `${process.env.EMAIL_FROM_NAME || "Al-Noor Mosque"} <${process.env.EMAIL_FROM || process.env.SMTP_USER || "no-reply@example.com"}>`;
  const transport = createTransport();

  if (!transport) {
    throw new Error("Email transport is not configured");
  }

  await transport.sendMail({
    from,
    to,
    subject,
    html,
  });
}

