export async function getAllMembers() {
  const supabase = await createClient();
  const { data } = await supabase
    .from("members")
    .select("*")
    .is("deleted_at", null)
    .order("full_name", { ascending: true });
  return (data as Member[]) ?? [];
}

export async function getFunds() {
  const supabase = await createClient();
  const [fundsResult, donationsResult] = await Promise.all([
    supabase
      .from("donation_funds")
      .select("*")
      .order("created_at", { ascending: false }),
    supabase
      .from("donations")
      .select("fund_id, amount")
      .eq("status", "completed")
=== getMembers ===
} = {}) {
  const supabase = await createClient();
  let query = supabase
    .from("incomes")
    .select("*", { count: "exact" })
    .is("deleted_at", null);

  if (search) {
    query = query.or(
      `source.ilike.%${search}%,income_category.ilike.%${search}%,description.ilike.%${search}%`
    );
  }
  if (category) query = query.eq("income_category", category);
  if (from) query = query.gte("date", from);
  if (to) query = query.lte("date", to);

  const fromIndex = (page - 1) * pageSize;
  const { data, count } = await query
    .order("date", { ascending: false })
    .range(fromIndex, fromIndex + pageSize - 1);

  return {
    data: (data as Income[]) ?? [],
    total: count ?? 0,
    page,
    pageSize,
    totalPages: Math.ceil((count ?? 0) / pageSize),
  };
}

export function memberFromMemberRow(row: Member): MemberListItem {
  return {
    source: "member",
    id: row.id,
    member_id: row.member_id,
