export async function getEventContributionRows(eventId: string) {
  const supabase = await createClient();
  const event = await getEventById(eventId);
  if (!event?.fund_id) return [];

  const [assignmentsRes, donationsRes, remindersRes, membersRes] = await Promise.all([
    supabase
      .from("event_members")
      .select("id, event_id, member_id, assigned_amount, created_at, created_by")
      .eq("event_id", eventId),
    supabase
      .from("donations")
      .select("id, donor_name, donor_phone, donor_email, fund_id, member_id, amount, payment_method, transaction_id, donation_date, is_anonymous, notes, status, receipt_number, created_at, updated_at, created_by, user_id, deleted_at")
      .eq("fund_id", event.fund_id)
      .eq("status", "completed")
      .is("deleted_at", null),
    supabase
      .from("contribution_reminder_emails")
      .select("*")
      .eq("event_id", eventId)
      .order("sent_at", { ascending: false }),
    supabase.from("members").select("id, full_name, phone, email").is("deleted_at", null),
  ]);

  const memberLookup = new Map<string, { full_name: string; phone: string | null; email: string | null }>();
  (membersRes.data ?? []).forEach((member: Member) => {
    memberLookup.set(member.id, { full_name: member.full_name, phone: member.phone, email: member.email });
  });

  const approvedByMember = new Map<string, Donation[]>();
  (donationsRes.data ?? []).forEach((donation: Donation) => {
    if (!donation.member_id) return;
    if (!approvedByMember.has(donation.member_id)) approvedByMember.set(donation.member_id, []);
    approvedByMember.get(donation.member_id)!.push(donation);
  });

  const lastReminderByMember = new Map<string, ContributionReminderEmail>();
  (remindersRes.data ?? []).forEach((row) => {
    if (!lastReminderByMember.has(row.member_id)) lastReminderByMember.set(row.member_id, row as ContributionReminderEmail);
  });

  return (assignmentsRes.data ?? []).map((row) => {
    const member = memberLookup.get(row.member_id);
    const approvedDonations = approvedByMember.get(row.member_id) ?? [];
    const paidAmount = approvedDonations.reduce((sum, donation) => sum + Number(donation.amount || 0), 0);
    const assignedAmount = Number(row.assigned_amount || event.contribution_amount || 0);
    const remainingAmount = Math.max(assignedAmount - paidAmount, 0);
    return {
      event_id: row.event_id,
      member_id: row.member_id,
      member_name: member?.full_name ?? "Unknown",
      phone: member?.phone ?? null,
      email: member?.email ?? null,
      assigned_amount: assignedAmount,
      paid_amount: paidAmount,
      remaining_amount: remainingAmount,
      status: paidAmount >= assignedAmount ? "completed" : "incomplete",
      approved_donations: approvedDonations,
      last_reminder: lastReminderByMember.get(row.member_id) ?? null,
    } as EventMemberContribution & { last_reminder: ContributionReminderEmail | null };
  });
}

export async function getEventContributionSummary(eventId: string) {
  const rows = await getEventContributionRows(eventId);
  const totalAssigned = rows.reduce((sum, row) => sum + Number(row.assigned_amount || 0), 0);
  const totalPaid = rows.reduce((sum, row) => sum + Number(row.paid_amount || 0), 0);
  const totalRemaining = rows.reduce((sum, row) => sum + Number(row.remaining_amount || 0), 0);
  const completed = rows.filter((row) => row.status === "completed").length;
  const incomplete = rows.filter((row) => row.status === "incomplete").length;
  return {
    totalAssigned,
    totalPaid,
    totalRemaining,
    completed,
    incomplete,
    completionPercent: rows.length ? Math.round((completed / rows.length) * 100) : 0,
  };
}

