import { NextRequest, NextResponse } from "next/server";

import { getCurrentProfile } from "@/lib/auth/session";
import { getPermissionsForRole } from "@/lib/access";
import { permissionsAllow } from "@/lib/permissions";
import { getAssignableMembers } from "@/lib/queries/admin";

/**
 * Members that can still be assigned to an event. Used by the admin picker so a
 * large member list is searched in Postgres instead of shipping every member to
 * the browser. The response carries member contact details, so the same
 * `event.manage` permission that gates the page also gates this endpoint.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ eventId: string }> }
) {
  const profile = await getCurrentProfile();
  if (!profile) {
    return NextResponse.json({ error: "Authentication required." }, { status: 401 });
  }
  if (profile.status !== "active") {
    return NextResponse.json({ error: "Your account is not active." }, { status: 403 });
  }

  const permissions = await getPermissionsForRole(profile.role);
  if (!permissionsAllow(permissions, "event.manage")) {
    return NextResponse.json(
      { error: "You do not have permission to manage event members." },
      { status: 403 }
    );
  }

  const { eventId } = await params;
  const search = request.nextUrl.searchParams.get("search") ?? "";

  const members = await getAssignableMembers(eventId, { search, limit: 300 });
  return NextResponse.json({ members });
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils/format";

/**
 * Contribution status is derived, never stored, so this badge is a pure function
 * of `paid >= assigned`. It sticks to the existing emerald/gold palette: emerald
 * for completed, a soft amber for incomplete, with an optional partial-payment
 * marker underneath.
 */
export function ContributionStatusBadge({
  status,
  paymentStage,
  showStage = true,
  className,
}: {
  status: "completed" | "incomplete";
  paymentStage?: "paid" | "partial" | "unpaid";
  showStage?: boolean;
  className?: string;
}) {
  const completed = status === "completed";
  const partial = paymentStage === "partial";

  return (
    <span
      className={cn(
        "inline-flex w-fit flex-col gap-0.5",
        className
      )}
    >
      <span
        className={cn(
          "inline-flex w-fit items-center gap-1.5 whitespace-nowrap rounded-full px-2.5 py-1 text-xs font-semibold ring-1 ring-inset",
          completed
            ? "bg-emerald-50 text-emerald-700 ring-emerald-600/20"
            : "bg-orange-50 text-orange-700 ring-orange-600/20"
        )}
      >
        <span aria-hidden="true">{completed ? "✓" : "○"}</span>
        {completed ? "Completed" : "Incomplete"}
      </span>
      {showStage && partial && (
        <span className="text-[10px] font-medium uppercase tracking-wide text-amber-700/80">
          Partial
        </span>
      )}
    </span>
  );
}

"use client";

import * as React from "react";
import { AlertTriangle, Target, TrendingUp, Users, Wallet } from "lucide-react";

import { cn, formatCurrency } from "@/lib/utils/format";
import type { EventContributionSummary } from "@/lib/queries/admin";

function SummaryCard({
  label,
  value,
  hint,
  tone = "neutral",
  icon: Icon,
}: {
  label: string;
  value: string;
  hint?: string;
  tone?: "neutral" | "emerald" | "gold" | "muted";
  icon: React.ComponentType<{ className?: string }>;
}) {
  return (
    <div
      className={cn(
        "rounded-2xl border border-black/[0.06] p-4 shadow-sm",
        tone === "emerald"
          ? "bg-[#064E3B]"
          : tone === "gold"
            ? "bg-[#C8A951]/[0.08]"
            : "bg-white"
      )}
    >
      <div className="flex items-center justify-between gap-2">
        <p
          className={cn(
            "text-xs font-medium uppercase tracking-wide",
            tone === "emerald" ? "text-white/70" : "text-muted-foreground"
          )}
        >
          {label}
        </p>
        <Icon
          className={cn(
            "h-4 w-4",
            tone === "emerald" ? "text-[#C8A951]" : "text-muted-foreground/60"
          )}
        />
      </div>
      <p
        className={cn(
          "mt-2 text-xl font-bold tabular-nums",
          tone === "emerald" ? "text-white" : "text-foreground"
        )}
      >
        {value}
      </p>
      {hint && (
        <p
          className={cn(
            "mt-1 text-xs",
            tone === "emerald" ? "text-white/60" : "text-muted-foreground"
          )}
        >
          {hint}
        </p>
      )}
    </div>
  );
}

export function ContributionSummaryCards({
  summary,
  perHeadAmount,
}: {
  summary: EventContributionSummary;
  perHeadAmount: number;
}) {
  const {
    memberCount,
    completed,
    incomplete,
    totalAssigned,
    fundCollected,
    totalRemaining,
    collectionPercent,
    completionPercent,
  } = summary;

  const clampedPercent = Math.max(0, Math.min(100, collectionPercent));

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <SummaryCard
          label="Target Collection"
          value={formatCurrency(totalAssigned)}
          hint={
            perHeadAmount > 0
              ? `${memberCount} member${memberCount === 1 ? "" : "s"} × ${formatCurrency(perHeadAmount)}`
              : "Set a per-head amount to calculate a target"
          }
          icon={Target}
          tone="gold"
        />
        <SummaryCard
          label="Collected"
          value={formatCurrency(fundCollected)}
          hint="Approved fund contributions"
          icon={Wallet}
          tone="emerald"
        />
        <SummaryCard
          label="Remaining"
          value={formatCurrency(totalRemaining)}
          hint={`Across ${incomplete} incomplete member${incomplete === 1 ? "" : "s"}`}
          icon={TrendingUp}
        />
        <SummaryCard
          label="Completed"
          value={`${completed} / ${memberCount}`}
          hint={`${completionPercent}% of members completed`}
          icon={Users}
        />
      </div>

      <div className="rounded-2xl border border-black/[0.06] bg-white p-4 shadow-sm">
        <div className="flex items-center justify-between gap-3">
          <p className="text-sm font-semibold text-foreground">Collection Progress</p>
          <p className="text-sm font-bold tabular-nums text-[#064E3B]">
            {clampedPercent}%
          </p>
        </div>
        <div className="mt-2 h-2.5 w-full overflow-hidden rounded-full bg-black/[0.06]">
          <div
            className="h-full rounded-full bg-[#064E3B] transition-[width] duration-500"
            style={{ width: `${clampedPercent}%` }}
          />
        </div>
        <div className="mt-2 flex flex-wrap items-center justify-between gap-2 text-xs text-muted-foreground">
          <span>
            {formatCurrency(fundCollected)} collected of {formatCurrency(totalAssigned)} expected
          </span>
          <span>
            Fund recorded {formatCurrency(totalAssigned > 0 ? totalAssigned - totalRemaining : 0)}
          </span>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-3 rounded-2xl border border-black/[0.06] bg-white p-4 shadow-sm">
        <div>
          <p className="text-[11px] uppercase tracking-wide text-muted-foreground">
            Total Assigned
          </p>
          <p className="mt-1 text-lg font-bold tabular-nums text-foreground">{memberCount}</p>
        </div>
        <div>
          <p className="text-[11px] uppercase tracking-wide text-muted-foreground">
            Completed
          </p>
          <p className="mt-1 text-lg font-bold tabular-nums text-emerald-700">{completed}</p>
        </div>
        <div>
          <p className="text-[11px] uppercase tracking-wide text-muted-foreground">
            Incomplete
          </p>
          <p className="mt-1 text-lg font-bold tabular-nums text-orange-700">{incomplete}</p>
        </div>
      </div>
    </div>
  );
}

/**
 * The event target is derived from its own assignments, which can drift from the
 * target stored on the linked fund. Surfacing the gap is enough: the fund is the
 * financial record of the fund and must never be rewritten from here.
 */
export function FundTargetMismatchNotice({
  summary,
}: {
  summary: EventContributionSummary;
}) {
  if (summary.fundTarget === null || summary.targetDifference === null) return null;
  if (Math.abs(summary.targetDifference) < 0.01) return null;

  const fundHigher = summary.targetDifference > 0;

  return (
    <div className="flex items-start gap-2.5 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900">
      <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-600" />
      <div>
        <p className="font-semibold">
          Event expectation differs from the fund target
        </p>
        <p className="mt-0.5 text-amber-800">
          This event expects {formatCurrency(summary.totalAssigned)}
          {summary.calculatedTarget !== summary.totalAssigned
            ? ` (${summary.memberCount} × ${formatCurrency(summary.calculatedTarget / Math.max(summary.memberCount, 1))})`
            : ""}
          , while the linked fund is targeting {formatCurrency(summary.fundTarget)} — a difference
          of {formatCurrency(Math.abs(summary.targetDifference))}
          {fundHigher ? " above" : " below"} the event expectation. The fund target was left
          unchanged; adjust it from the Funds page if needed.
        </p>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { useEffect, useMemo, useState, useTransition } from "react";
import { toast } from "sonner";
import { Loader2, UserPlus, Users } from "lucide-react";

import { cn, formatCurrency } from "@/lib/utils/format";
import { addEventMembers } from "@/lib/actions/admin";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { ErrorMessage } from "@/components/forms/error-message";
import { EmptyState } from "@/components/forms/empty-state";

type AssignableMember = {
  id: string;
  member_code: string | null;
  full_name: string;
  phone: string | null;
  email: string | null;
};

/**
 * Assigns existing members to an event. Only ids travel to the server, so member
 * personal data is never duplicated, and the assignable list is searched through
 * the server so a large members table does not have to be shipped to the browser.
 */
export function EventMemberPickerDialog({
  open,
  onOpenChange,
  eventId,
  defaultAssignedAmount,
  onAssigned,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  eventId: string;
  defaultAssignedAmount: number;
  onAssigned?: () => void;
}) {
  const [members, setMembers] = useState<AssignableMember[]>([]);
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [amount, setAmount] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isSaving, startSaveTransition] = useTransition();

  useEffect(() => {
    if (!open) return;

    const controller = new AbortController();
    const timer = setTimeout(async () => {
      setLoading(true);
      try {
        const response = await fetch(
          `/api/admin/events/${eventId}/assignable-members?search=${encodeURIComponent(search)}`,
          { signal: controller.signal }
        );
        if (!response.ok) throw new Error("Could not load members");
        const payload = (await response.json()) as { members?: AssignableMember[] };
        setMembers(payload.members ?? []);
        setError(null);
      } catch (fetchError) {
        if ((fetchError as Error).name === "AbortError") return;
        setError("Unable to load members. Please try again.");
      } finally {
        setLoading(false);
      }
    }, 250);

    return () => {
      controller.abort();
      clearTimeout(timer);
    };
  }, [open, eventId, search]);

  const allSelected = members.length > 0 && members.every((member) => selected.has(member.id));

  const effectiveAmount = amount.trim() === "" ? defaultAssignedAmount : Number(amount);
  const effectiveTotal = effectiveAmount * selected.size;

  const toggle = (id: string) => {
    setSelected((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const toggleAll = () => {
    setSelected((current) => {
      if (allSelected) {
        const next = new Set(current);
        members.forEach((member) => next.delete(member.id));
        return next;
      }
      const next = new Set(current);
      members.forEach((member) => next.add(member.id));
      return next;
    });
  };

  const handleSubmit = () => {
    if (selected.size === 0) {
      setError("Select at least one member to assign.");
      return;
    }
    if (Number.isNaN(effectiveAmount) || effectiveAmount < 0) {
      setError("Assigned amount cannot be negative.");
      return;
    }

    const formData = new FormData();
    formData.set("event_id", eventId);
    formData.set("assigned_amount", String(effectiveAmount));
    selected.forEach((id) => formData.append("member_ids", id));

    startSaveTransition(async () => {
      const result = await addEventMembers(formData);
      if (result.error) {
        toast.error(result.error);
        return;
      }
      toast.success(result.message ?? "Members assigned");
      setSelected(new Set());
      setSearch("");
      setAmount("");
      onAssigned?.();
      onOpenChange(false);
    });
  };

  const selectionSummary = useMemo(
    () => `${selected.size} selected · ${formatCurrency(effectiveTotal)}`,
    [selected.size, effectiveTotal]
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-2xl rounded-2xl">
        <DialogHeader>
          <DialogTitle>Add Members</DialogTitle>
          <DialogDescription>
            Members already assigned to this event are not listed. Assigning a member sets their
            contribution target from the per-head amount below.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-3">
          <div className="grid gap-3 sm:grid-cols-[1fr_11rem]">
            <div className="space-y-1.5">
              <Label htmlFor="member-search">Search members</Label>
              <Input
                id="member-search"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Name, ID or phone..."
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="assigned-amount">Assigned amount</Label>
              <Input
                id="assigned-amount"
                type="number"
                min={0}
                step="0.01"
                value={amount}
                onChange={(event) => setAmount(event.target.value)}
                placeholder={String(defaultAssignedAmount || 0)}
              />
            </div>
          </div>

          <div className="rounded-xl border border-black/[0.06]">
            <div className="flex items-center justify-between gap-2 border-b border-black/[0.06] px-3 py-2">
              <label className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
                <Checkbox
                  checked={allSelected}
                  onCheckedChange={toggleAll}
                  disabled={members.length === 0}
                  aria-label="Select all listed members"
                />
                {loading ? "Loading..." : `Select all (${members.length})`}
              </label>
              <span className="text-xs text-muted-foreground">{selectionSummary}</span>
            </div>

            <div className="max-h-64 overflow-y-auto">
              {members.length === 0 && !loading ? (
                <div className="p-4">
                  <EmptyState
                    icon={Users}
                    title="No available members"
                    description={
                      search
                        ? "No members match this search."
                        : "Every active member is already assigned to this event."
                    }
                  />
                </div>
              ) : (
                members.map((member) => (
                  <label
                    key={member.id}
                    className="flex cursor-pointer items-center gap-3 border-b border-black/[0.04] px-3 py-2.5 last:border-0 hover:bg-black/[0.02]"
                  >
                    <Checkbox
                      checked={selected.has(member.id)}
                      onCheckedChange={() => toggle(member.id)}
                      aria-label={`Assign ${member.full_name}`}
                    />
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-sm font-medium text-foreground">
                        {member.full_name}
                      </span>
                      <span className="block truncate text-xs text-muted-foreground">
                        {member.member_code ? `${member.member_code} · ` : ""}
                        {member.phone ?? "No phone"}
                      </span>
                    </span>
                    {member.email ? (
                      <span className="hidden shrink-0 truncate text-xs text-muted-foreground sm:block">
                        {member.email}
                      </span>
                    ) : (
                      <span className="shrink-0 text-[10px] font-medium uppercase text-amber-700">
                        No email
                      </span>
                    )}
                  </label>
                ))
              )}
            </div>
          </div>

          <ErrorMessage message={error ?? undefined} />
        </div>

        <DialogFooter className="flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2">
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isSaving}>
            Cancel
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={isSaving || loading || selected.size === 0}
            className={cn("bg-[#064E3B] text-white hover:bg-[#065F46]")}
          >
            {isSaving ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Assigning...
              </>
            ) : (
              <>
                <UserPlus className="mr-2 h-4 w-4" />
                Assign {selected.size || ""}
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as React from "react";
import { useActionState, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { AlertCircle, Loader2, Mail } from "lucide-react";

import { formatCurrency } from "@/lib/utils/format";
import { buildReminderMessage, buildReminderSubject } from "@/lib/reminders";
import { sendContributionReminder } from "@/lib/actions/admin";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { ErrorMessage } from "@/components/forms/error-message";
import { ContributionStatusBadge } from "@/components/admin/contribution-status-badge";
import type { EventMemberContribution } from "@/types/database";

/**
 * Reminder composer for a single member.
 *
 * The address, name and all three amounts are read from the member profile and
 * the derived contribution row, so the admin never types an email address and
 * never edits a financial figure. Only the subject and the wording are theirs to
 * change, and the send itself happens on the server.
 */
export function ContributionReminderDialog({
  open,
  onOpenChange,
  row,
  eventName,
  dueDate,
  mosqueName,
  onSent,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  row: EventMemberContribution | null;
  eventName: string;
  dueDate: string | null;
  mosqueName: string;
  onSent?: () => void;
}) {
  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");
  const [state, formAction, isSending] = useActionState(sendContributionReminder, {});

  const defaults = useMemo(() => {
    if (!row) return null;
    return {
      subject: buildReminderSubject(eventName, mosqueName),
      message: buildReminderMessage({
        memberName: row.member_name,
        eventName,
        assignedAmount: row.assigned_amount,
        paidAmount: row.paid_amount,
        remainingAmount: row.remaining_amount,
        dueDate,
        mosqueName,
      }),
    };
  }, [row, eventName, dueDate, mosqueName]);

  // Prefill from the selected member every time the modal opens for them.
  useEffect(() => {
    if (!open || !defaults) return;
    setSubject(defaults.subject);
    setMessage(defaults.message);
  }, [open, defaults]);

  useEffect(() => {
    if (!state.success) return;
    toast.success("Email sent successfully", {
      description: `Delivered to ${row?.email ?? "the member"}.`,
    });
    onSent?.();
    onOpenChange(false);
  }, [state, row, onOpenChange, onSent]);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!row) return;

    const formData = new FormData();
    formData.set("event_id", row.event_id);
    formData.set("member_id", row.member_id);
    formData.set("subject", subject);
    formData.set("message", message);
    formAction(formData);
  };

  if (!row) return null;

  return (
    <Dialog open={open} onOpenChange={isSending ? undefined : onOpenChange}>
      <DialogContent className="sm:max-w-xl rounded-2xl">
        <DialogHeader>
          <DialogTitle>Send Contribution Reminder</DialogTitle>
          <DialogDescription>
            Review the details below, adjust the wording if needed, then send. The email is sent
            from the server using the mosque&apos;s configured sender address.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label>Member</Label>
            <div className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-black/[0.06] bg-black/[0.02] px-3 py-2.5">
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold text-foreground">{row.member_name}</p>
                <p className="truncate text-xs text-muted-foreground">
                  {row.member_code ? `${row.member_code} · ` : ""}
                  {row.email ?? "No email on profile"}
                </p>
              </div>
              <ContributionStatusBadge
                status={row.status}
                paymentStage={row.payment_stage}
                showStage={false}
              />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-2">
            <div className="rounded-lg bg-[#064E3B]/[0.04] px-3 py-2">
              <p className="text-[10px] uppercase tracking-wide text-muted-foreground">Assigned</p>
              <p className="mt-0.5 text-sm font-bold tabular-nums text-[#064E3B]">
                {formatCurrency(row.assigned_amount)}
              </p>
            </div>
            <div className="rounded-lg bg-emerald-50 px-3 py-2">
              <p className="text-[10px] uppercase tracking-wide text-emerald-700/70">Paid</p>
              <p className="mt-0.5 text-sm font-bold tabular-nums text-emerald-700">
                {formatCurrency(row.paid_amount)}
              </p>
            </div>
            <div className="rounded-lg bg-orange-50 px-3 py-2">
              <p className="text-[10px] uppercase tracking-wide text-orange-700/70">Remaining</p>
              <p className="mt-0.5 text-sm font-bold tabular-nums text-orange-700">
                {formatCurrency(row.remaining_amount)}
              </p>
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="reminder-to">To</Label>
            <Input
              id="reminder-to"
              readOnly
              value={row.email ?? "No email on profile"}
              className="bg-black/[0.02] text-muted-foreground"
            />
            {!row.email && (
              <p className="flex items-center gap-1.5 text-xs font-medium text-amber-700">
                <AlertCircle className="h-3.5 w-3.5" />
                Add an email address to this member&apos;s profile to send a reminder.
              </p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="reminder-subject">Subject</Label>
            <Input
              id="reminder-subject"
              value={subject}
              onChange={(event) => setSubject(event.target.value)}
              required
              minLength={2}
            />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="reminder-message">Message</Label>
            <Textarea
              id="reminder-message"
              value={message}
              onChange={(event) => setMessage(event.target.value)}
              required
              minLength={10}
              rows={12}
              className="font-mono text-xs leading-relaxed"
            />
          </div>

          {state.error && <ErrorMessage message={state.error} />}

          <DialogFooter className="flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isSending}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSending || !row.email}
              className="bg-[#064E3B] text-white hover:bg-[#065F46]"
            >
              {isSending ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Sending...
                </>
              ) : (
                <>
                  <Mail className="mr-2 h-4 w-4" />
                  Send Email
                </>
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as React from "react";

import { formatCurrency, formatDate } from "@/lib/utils/format";
import { PAYMENT_METHODS } from "@/constants";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { ContributionStatusBadge } from "@/components/admin/contribution-status-badge";
import type { EventMemberContribution } from "@/types/database";

function methodLabel(value: string | null) {
  if (!value) return "—";
  return PAYMENT_METHODS.find((method) => method.value === value)?.label ?? value;
}

/**
 * Read-only breakdown of one member's contribution. It renders the same approved
 * donations the table aggregates, so there is no second record to keep in sync.
 */
export function ContributionDetailDialog({
  open,
  onOpenChange,
  row,
  eventName,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  row: EventMemberContribution | null;
  eventName: string;
}) {
  if (!row) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg rounded-2xl">
        <DialogHeader>
          <DialogTitle>{row.member_name}</DialogTitle>
          <DialogDescription>
            Contribution details for {eventName}
            {row.member_code ? ` · ${row.member_code}` : ""}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          <div className="grid grid-cols-3 gap-2">
            <div className="rounded-lg bg-[#064E3B]/[0.04] px-3 py-2">
              <p className="text-[10px] uppercase tracking-wide text-muted-foreground">Required</p>
              <p className="mt-0.5 text-sm font-bold tabular-nums text-[#064E3B]">
                {formatCurrency(row.assigned_amount)}
              </p>
            </div>
            <div className="rounded-lg bg-emerald-50 px-3 py-2">
              <p className="text-[10px] uppercase tracking-wide text-emerald-700/70">Total Paid</p>
              <p className="mt-0.5 text-sm font-bold tabular-nums text-emerald-700">
                {formatCurrency(row.paid_amount)}
              </p>
            </div>
            <div className="rounded-lg bg-orange-50 px-3 py-2">
              <p className="text-[10px] uppercase tracking-wide text-orange-700/70">Remaining</p>
              <p className="mt-0.5 text-sm font-bold tabular-nums text-orange-700">
                {formatCurrency(row.remaining_amount)}
              </p>
            </div>
          </div>

          <div className="rounded-xl border border-black/[0.06]">
            <p className="border-b border-black/[0.06] px-3 py-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
              Approved Payments
            </p>
            {row.approved_donations.length === 0 ? (
              <p className="px-3 py-6 text-center text-xs text-muted-foreground">
                No approved payments recorded for this member yet.
              </p>
            ) : (
              <ul className="divide-y divide-black/[0.04]">
                {row.approved_donations.map((donation) => (
                  <li
                    key={donation.id}
                    className="flex items-center justify-between gap-3 px-3 py-2.5"
                  >
                    <div className="min-w-0">
                      <p className="text-sm font-medium text-foreground">
                        {formatDate(donation.donation_date)}
                      </p>
                      <p className="truncate text-xs text-muted-foreground">
                        {methodLabel(donation.payment_method)}
                        {donation.transaction_id ? ` · ${donation.transaction_id}` : ""}
                      </p>
                    </div>
                    <p className="shrink-0 text-sm font-bold tabular-nums text-emerald-700">
                      {formatCurrency(Number(donation.amount))}
                    </p>
                  </li>
                ))}
              </ul>
            )}
          </div>

          <div className="flex items-center justify-between rounded-xl bg-black/[0.02] px-3 py-2.5">
            <div className="text-xs text-muted-foreground">
              <p>
                {row.email ?? "No email on profile"}
              </p>
              {row.last_reminder && (
                <p className="mt-0.5">
                  Last reminder {formatDate(row.last_reminder.sent_at, "dd MMM yyyy, h:mm a")}
                </p>
              )}
            </div>
            <ContributionStatusBadge
              status={row.status}
              paymentStage={row.payment_stage}
              showStage={false}
            />
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

