cat > /tmp/opencode/verify-contribution.mjs <<'EOF'
// Verifies the spec's test case (43) against the real deriveContribution source.
import { readFileSync } from "node:fs";
import { writeFileSync, mkdirSync } from "node:fs";

const src = readFileSync(
  "/media/taseen/New Volume/New folder (3)/MMS-v1.0/src/lib/utils/contribution.ts",
  "utf8"
).replace(/export type[\s\S]*?;\n/g, "").replace(/: [A-Za-z<>\[\]| ]+(?=[,)=])/g, "");
mkdirSync("/tmp/opencode/cc", { recursive: true });
writeFileSync("/tmp/opencode/cc/m.mjs", src);
const { deriveContribution } = await import("/tmp/opencode/cc/m.mjs");

let pass = 0, fail = 0;
const check = (name, actual, expected) => {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  ok ? pass++ : fail++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}`);
  if (!ok) console.log(`      expected ${JSON.stringify(expected)}\n      got      ${JSON.stringify(actual)}`);
};

const PER_HEAD = 520;

// --- Spec 43: initial state, 500 members, nothing paid
let rows = Array.from({ length: 500 }, () => deriveContribution(PER_HEAD, []));
check("initial: collected 0 / completed 0 / incomplete 500",
  [rows.reduce((s,r)=>s+r.paid_amount,0),
   rows.filter(r=>r.status==="completed").length,
   rows.filter(r=>r.status==="incomplete").length,
   rows.reduce((s,r)=>s+r.assigned_amount,0)],
  [0, 0, 500, 260000]);

// --- Rahim pays 520 and is approved
const rahim = deriveContribution(PER_HEAD, [520]);
check("Rahim after approval: paid 520, remaining 0, Completed",
  [rahim.paid_amount, rahim.remaining_amount, rahim.status], [520, 0, "completed"]);

// --- Karim pays 300 and is approved (partial)
const karimPartial = deriveContribution(PER_HEAD, [300]);
check("Karim partial: paid 300, remaining 220, Incomplete, stage partial",
  [karimPartial.paid_amount, karimPartial.remaining_amount, karimPartial.status, karimPartial.payment_stage],
  [300, 220, "incomplete", "partial"]);

// --- Karim later pays 220 -> auto-completes
const karimDone = deriveContribution(PER_HEAD, [300, 220]);
check("Karim second payment: paid 520, remaining 0, Completed",
  [karimDone.paid_amount, karimDone.remaining_amount, karimDone.status], [520, 0, "completed"]);

// --- Spec 10: overpayment keeps real paid, clamps remaining at 0
const over = deriveContribution(PER_HEAD, [600]);
check("Overpayment: paid 600 preserved, remaining 0, Completed",
  [over.paid_amount, over.remaining_amount, over.status], [600, 0, "completed"]);
check("Overpayment never yields negative remaining", over.remaining_amount >= 0, true);

// --- Event total after Rahim + Karim complete
rows = Array.from({ length: 500 }, () => deriveContribution(PER_HEAD, []));
rows[0] = rahim;
check("event totals: collected 520, completed 1/500",
  [rows.reduce((s,r)=>s+r.paid_amount,0), rows.filter(r=>r.status==="completed").length], [520, 1]);

// --- Unpaid stage
check("unpaid stage", deriveContribution(PER_HEAD, []).payment_stage, "unpaid");

// --- Zero assigned amount must not mark everyone Completed
const noTarget = deriveContribution(0, []);
check("zero assigned + no payment -> Incomplete (not Completed)", noTarget.status, "incomplete");
check("zero assigned + payment -> Completed", deriveContribution(0, [100]).status, "completed");

// --- Per-member override
check("override 1040 with 520 paid -> Incomplete, remaining 520",
  [deriveContribution(1040, [520]).remaining_amount, deriveContribution(1040,[520]).status], [520, "incomplete"]);

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
EOF
node /tmp/opencode/verify-contribution.mjs

