console.log("\nSTRIPPED MESSAGE (admin removed closing):");
console.log("  'JazakAllahu Khairan' count:", count(stripped, "JazakAllahu Khairan"), "(footer restored)");

const arabic = buildReminderHtml({ ...base, adminMessage: "Assalamu Alaikum Karim,\n\nBarakallahu feek.\n\nJazakAllahu Khairan wa barak." });
console.log("\nARABIC-STYLE CLOSING:");
console.log("  'JazakAllahu Khairan' count:", count(arabic, "JazakAllahu Khairan"), "(no extra footer appended)");

const empty = buildReminderHtml({ ...base, adminMessage: "" });
