input.content:
import { buildReminderHtml } from "./email.js";
import { buildReminderMessage } from "./reminders.js";

const count = (h, s) => (h.match(new RegExp(s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g")) || []).length;

const base = {
  memberName: "Karim Uddin",
  eventName: "Tarabir Hadiya",
  assignedAmount: 520,
  paidAmount: 300,
  remainingAmount: 220,
  dueDate: "2026-10-20",
  mosqueName: "Al-Noor Mosque",
  mosqueAddress: "12 Green Road",
  mosquePhone: "+880 1711",
  logoUrl: null,
};

const t = (n, h) =>
  console.log(`  ${n.padEnd(24)} signoff=${count(h, "JazakAllahu Khairan")} extraSignature=${count(h, ">Al-Noor Mosque<")}`);

console.log("footer de-duplication across editable-message cases:");
t("default wording", buildReminderHtml({ ...base, adminMessage: buildReminderMessage(base) }));
t("admin removed closing", buildReminderHtml({ ...base, adminMessage: "Assalamu Alaikum Karim,\n\nPlease pay soon." }));
t("sign-off, no signature", buildReminderHtml({ ...base, adminMessage: "Assalamu Alaikum,\n\nJazakAllahu Khairan." }));
t("signature only", buildReminderHtml({ ...base, adminMessage: "Assalamu Alaikum,\n\nAl-Noor Mosque" }));
t("empty message", buildReminderHtml({ ...base, adminMessage: "" }));
t("arabic closing", buildReminderHtml({ ...base, adminMessage: "Assalamu Alaikum,\n\nJazakAllahu Khairan wa barak." }));

console.log("\nregression checks:");
console.log("  escaping holds:", buildReminderHtml({ ...base, adminMessage: "<script>x</script>" }).includes("&lt;script&gt;"));
console.log("  no undefined:", !buildReminderHtml({ ...base, adminMessage: "hi" }).includes("undefined"));
console.log("  mosque header always present:", buildReminderHtml({ ...base, adminMessage: "" }).includes('letter-spacing:2px'));

