import { buildReminderHtml } from "./email.js";
import { buildReminderMessage } from "./reminders.js";
const base={memberName:"Karim Uddin",eventName:"Tarabir Hadiya",assignedAmount:520,paidAmount:300,remainingAmount:220,dueDate:"2026-10-20",mosqueName:"Al-Noor Mosque",mosqueAddress:"",mosquePhone:"",logoUrl:null};
const foot = (msg) => {
  const h = buildReminderHtml({...base, adminMessage: msg});
  // footer paragraphs use these exact margin/font combos
  return {
    signOffFooter: h.includes('margin:24px 0 0;font-size:15px'),
    signatureFooter: h.includes('margin:4px 0 0;font-size:14px;color:#5b6b62'),
  };
};
const rows = [
  ["default wording", buildReminderMessage(base)],
  ["closing removed", "Assalamu Alaikum Karim,\n\nPlease pay soon."],
  ["signoff only", "Assalamu Alaikum,\n\nJazakAllahu Khairan."],
  ["signature only", "Assalamu Alaikum,\n\nAl-Noor Mosque"],
  ["empty", ""],
];
for (const [n,m] of rows) {
  const f = foot(m);
  console.log(`  ${n.padEnd(20)} adds sign-off:${String(f.signOffFooter).padEnd(5)} adds signature:${f.signatureFooter}`);
}
EOF
node run2.mjs

