cd /tmp/opencode && rm -rf tmpl && mkdir -p tmpl && SRC="/media/taseen/New Volume/New folder (3)/MMS-v1.0" && cp "$SRC/src/lib/reminders.ts" tmpl/ && cd tmpl && npx --prefix "$SRC" tsc reminders.ts --outDir out --module esnext --target es2022 --moduleResolution bundler 2>&1|head -3; cat > out/t.mjs <<'EOF'
import { buildBulkReminderMessageTemplate, buildBulkReminderSubjectTemplate, renderReminderTemplate, findUnknownPlaceholders } from "./reminders.js";

const karim = { memberName:"Karim Ahmed", eventName:"Tarabir Hadiya", assignedAmount:520, paidAmount:300, remainingAmount:220, dueDate:"2027-03-15", mosqueName:"Al-Noor Mosque" };
const rahim = { ...karim, memberName:"Rahim Uddin", paidAmount:0, remainingAmount:520 };

const subj = buildBulkReminderSubjectTemplate();
const msg  = buildBulkReminderMessageTemplate();

console.log("=== SUBJECT (Rahim) ===");
console.log(renderReminderTemplate(subj, rahim));
console.log("\n=== MESSAGE (Karim) ===");
console.log(renderReminderTemplate(msg, karim));
console.log("\n=== MESSAGE (Rahim) ===");
console.log(renderReminderTemplate(msg, rahim));

console.log("\n=== personalization guarantees ===");
const k = renderReminderTemplate(msg, karim), r = renderReminderTemplate(msg, rahim);
console.log("  individual emails (contents differ):", k !== r);
console.log("  Karim has 300/220, not Rahim's 0/520:", k.includes("৳300") && k.includes("৳220") && !k.includes("৳520\n"));
console.log("  Rahim has 0/520:", r.includes("৳0") && r.includes("Remaining: ৳520"));
console.log("  no leftover placeholders in either:", !/\{\{.*\}\}/.test(k) && !/\{\{{.*\}\}/.test(r));
console.log("  names not cross-contaminated:", !k.includes("Rahim") && !r.includes("Karim"));
console.log("  whitespace-tolerant braces:", renderReminderTemplate("Hi {{ member_name }} / {{event_name}}", karim).includes("Karim Ahmed / Tarabir Hadiya"));

console.log("\n=== unknown placeholder detection ===");
console.log("  typo found:", JSON.stringify(findUnknownPlaceholders("{{membername}} {{asigned_amount}} {{event_name}}")));
console.log("  none found:", JSON.stringify(findUnknownPlaceholders(msg)));
console.log("  spaced typo found:", JSON.stringify(findUnknownPlaceholders("{{ asigned_amount }}")));

console.log("\n=== unknown placeholders survive render (server blocks send first) ===");
console.log("  literal preserved:", renderReminderTemplate("Hi {{bogus}}", karim) === "Hi {{bogus}}");
EOF
node out/t.mjs

