input.newString:
const incomplete = rows
    .filter((row) => row.status === "incomplete")
    // Stable queue order, so the cursor below can never repeat or skip anyone.
    .sort((a, b) => a.member_id.localeCompare(b.member_id));
  if (!incomplete.length) {
    return { error: "All assigned members have completed their contribution." };
  }

  // Resume after the last member of the previous batch. Sent as an id rather than
  // an index because the incomplete set can shrink between batches.
  const afterMemberId = String(formData.get("after_member_id") ?? "");
  const startIndex = afterMemberId
    ? incomplete.findIndex((row) => row.member_id === afterMemberId) + 1
    : 0;
  if (startIndex <= 0 && afterMemberId) {
    // The cursor member has since completed and left the queue; restart safely
    // rather than guessing a position.
    return {
      error: "The reminder queue changed while sending. Please start the run again.",
    };
  }

  const { data: settings } = await supabase

