export async function getMyDonations({
  userId,
  page = 1,
  pageSize = 20,
}: {
  userId: string;
  page?: number;
  pageSize?: number;
} = {
  userId: "",
}) {
  const supabase = await createClient();

  const fromIndex = (page - 1) * pageSize;
  const { data, count } = await supabase
    .from("donations")
    .select("*, donation_funds(name)", { count: "exact" })
    .eq("user_id", userId)
    .is("deleted_at", null)
