    (sum, row) => sum + Number((row as { amount: number }).amount ?? 0),
    0
  );

  return {
    data: (data as (Donation & { donation_funds: { name: string } | null })[]) ?? [],
    total: count ?? 0,
    totalAmount,
    page,
    pageSize,
    totalPages: Math.ceil((count ?? 0) / pageSize),
  };
}
