+          >
+            {isSaving ? (
+              <>
+                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
+                Saving...
+              </>
+            ) : (
+              "Save Amount"
+            )}
+          </Button>
+        </div>
+      </DialogFooter>
+    </form>
