// Simulates the bulk batching contract end-to-end (server logic mirrored).
const BATCH = 10;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function makeQueue(n, {completed, noEmail}) {
  const rows = [];
  for (let i = 0; i < n; i++) {
    rows.push({
      member_id: `m${String(i).padStart(4,"0")}`,
      member_name: `Member ${i}`,
      email: noEmail.includes(i) ? null : `m${i}@example.com`,
      status: completed.includes(i) ? "completed" : "incomplete",
    });
  }
  return rows.sort((a,b)=>a.member_id.localeCompare(b.member_id));
}

function runBatch(incomplete, afterCursor) {
  const startIndex = afterCursor ? incomplete.filter(r=>r.member_id<=afterCursor).length : 0;
  const batch = incomplete.slice(startIndex, startIndex+BATCH);
  const results=[];
  for (const r of batch) {
    if (!r.email || !EMAIL.test(r.email)) { results.push({...r, status:"skipped"}); continue; }
    results.push({...r, status:"sent"});
  }
  const cursor = batch[batch.length-1]?.member_id ?? afterCursor;
  const hasMore = total_of(incomplete) - incomplete.filter(r=>r.member_id<=cursor).length > 0;
  return { results, cursor, hasMore };
}
const total_of = (a)=>a.length;

function simulate(rows, onMemberComplete) {
  const totals={sent:0,failed:0,skipped:0,processed:0};
  let cursor="", batches=0, emailed=new Set(), dupes=[];
  for(;;){
    let incomplete = rows.filter(r=>r.status==="incomplete").sort((a,b)=>a.member_id.localeCompare(b.member_id));
    const { results, cursor: next, hasMore } = runBatch(incomplete, cursor);
    batches++;
    for (const r of results) {
      totals[r.status]++;
      if (r.status==="sent") { if(emailed.has(r.member_id)) dupes.push(r.member_id); emailed.add(r.member_id); }
      totals.processed++;
    }
    cursor = next;
    onMemberComplete?.(batches);
    if (!hasMore) break;
    if (batches > 500) break;
  }
  return { totals, batches, dupes, emailedCount: emailed.size };
}

// ---- Acceptance test from the spec: 500 assigned, 200 completed, 300 incomplete, 10 no email
const completed=[...Array(200).keys()];
const noEmail=[5,15,25,35,45,55,65,75,85,95];
const rows=makeQueue(500,{completed,noEmail});
const r=simulate(rows);
console.log("SCENARIO: 500 assigned / 200 completed / 300 incomplete / 10 without email");
console.log("  sent:", r.totals.sent, "(expected 290)");
console.log("  skipped:", r.totals.skipped, "(expected 10)");
console.log("  failed:", r.totals.failed, "(expected 0)");
console.log("  processed:", r.totals.processed, "(expected 300)");
console.log("  batches:", r.batches);
console.log("  no duplicates:", r.dupes.length===0);
console.log("  completed members never emailed:", r.emailedCount===290);

// ---- Queue shrinks mid-run (member completes between batches)
const rows2=makeQueue(50,{completed:[],noEmail:[]});
const r2=simulate(rows2,(b)=>{ if(b===2) rows2.find(x=>x.member_id==="m0007").status="completed"; });
const sent2=new Set();
console.log("\nSCENARIO: member completes mid-run");
console.log("  no duplicates:", r2.dupes.length===0, r2.dupes.length?r2.dupes:"");
console.log("  processed+skipped == incomplete at end:", r2.totals.processed === rows2.filter(x=>x.status==="incomplete").length);
console.log("  the completed member was not emailed:", r2.totals.sent===49);
EOF
