  const { data: old, error: readError } = await supabase
    .from("event_members")
    .select("assigned_amount")
    .eq("event_id", parsed.data.event_id)
    .eq("member_id", parsed.data.member_id)
    .maybeSingle();
  if (readError) return { error: readError.message };

