// Mirror of isDeliverableEmail from src/lib/reminders.ts
function isDeliverableEmail(value) {
  if (!value) return false;
  const email = value.trim();
  if (email.length < 3 || email.length > 254) return false;
  if (/\s/.test(email)) return false;
  const at = email.indexOf("@");
  if (at < 1 || at !== email.lastIndexOf("@")) return false;
  const local = email.slice(0, at);
  const domain = email.slice(at + 1);
  if (local.length > 64) return false;
  const dot = domain.lastIndexOf(".");
  if (dot < 1 || dot === domain.length - 1) return false;
  if (domain.includes("..")) return false;
  if (local.startsWith(".") || local.endsWith(".") || local.includes("..")) return false;
  return /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$/.test(email);
}

const oldPreview = (e) => Boolean(e);
const cases = [
  ["karim@example.com", true], ["rahim.mosque@bd.org", true],
  ["a_b-c@sub.domain.co", true], ["user+tag@example.com", true],
  ["  spaced@example.com  ", true],
  [null, false], [undefined, false], ["", false],
  ["karim@", false], ["@example.com", false], ["karim@example", false],
  ["karim @example.com", false], ["karim@exam ple.com", false],
  ["karim@@example.com", false], [".karim@example.com", false],
  ["karim.@example.com", false], ["kar..im@example.com", false],
  ["karim@example..com", false], ["karim@.com", false],
  ["karim@localhost", false], ["karim@example.c", true],
];

let mismatches = 0;
for (const [input, expected] of cases) {
  const shared = isDeliverableEmail(input);
  const naive = oldPreview(input);
  const ok = shared === expected;
  if (!ok) mismatches++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${JSON.stringify(input)?.padEnd(28)} shared=${String(shared).padEnd(5)} oldPreview=${String(naive).padEnd(5)}${naive!==shared ? "  <-- preview would have MISCOUNTED" : ""}`);
}
console.log(`\nmismatches vs spec: ${mismatches}`);
console.log(`cases where old Boolean() preview disagreed with server: ${cases.filter(([i])=>oldPreview(i)!==isDeliverableEmail(i)).length}`);
EOF
