// Models the state machine: does a reopen show a FRESH dialog, and does the
// error path ever strand the UI on "sending"?
function makeModel({ radixCallsOnOpenChangeOnPropChange }) {
  let st = { phase: "confirm", processed: 0, error: null, sent: 0, locked: false };
  let wasOpen = false;
  const listeners = [];

  const set = (patch) => { Object.assign(st, patch); listeners.forEach(l => l()); };

  const resetForOpen = () => set({ phase: "confirm", processed: 0, error: null, sent: 0 });

  // Props flip open externally.
  const applyProp = (open) => {
    if (open !== wasOpen) {
      wasOpen = open;
      if (open) resetForOpen();          // <-- the new fix
    }
    // Radix's onOpenChange is NOT invoked by a controlled prop change.
    if (radixCallsOnOpenChangeOnPropChange && open) resetForOpen();
  };

  const close = () => { if (st.phase === "sending") return "blocked"; applyProp(false); return "closed"; };

  const runSend = async (failAt) => {
    if (st.locked) return "IGNORED (duplicate click)";
    st.locked = true; set({ phase: "sending", error: null });
    try {
      for (let b = 0; b < 5; b++) {
        if (b === failAt) throw new Error("network");
        set({ processed: st.processed + 10, sent: st.sent + 10 });
      }
      set({ phase: "done" });
      return "completed";
    } catch {
      set({ phase: "done", error: "interrupted" });
      return "caught";
    } finally {
      st.locked = false;
    }
  };

  return { get st() { return st; }, applyProp, close, runSend, onChange: l => listeners.push(l) };
}

// OLD behaviour: reset only inside onOpenChange(true), which a controlled prop
// change never triggers, plus no try/catch and no lock.
function makeOldModel() {
  let st = { phase: "confirm", processed: 0, error: null, locked: false };
  const set = (p) => Object.assign(st, p);
  const applyProp = () => { /* no reset: onOpenChange never fires */ };
  const close = () => "closed";
  const runSend = async (failAt) => {
    set({ phase: "sending" });
    for (let b = 0; b < 5; b++) {
      if (b === failAt) throw new Error("network");   // uncaught -> caller never sees done
      set({ processed: st.processed + 10 });
    }
    set({ phase: "done" });
  };
  return { get st() { return st; }, applyProp, close, runSend };
}

console.log("--- A. old: reopen after a completed run ---");
const old = makeOldModel();
old.applyProp(true);
await old.runSend(99);
old.applyProp(false);
old.applyProp(true);                       // parent reopens
console.log(`  old  phase=${old.st.phase}  <- stale, shows previous run`);

console.log("--- B. new: reopen after a completed run ---");
const m = makeModel({ radixCallsOnOpenChangeOnPropChange: false });
m.applyProp(true);
await m.runSend(99);
m.close();
m.applyProp(true);
console.log(`  new  phase=${m.st.phase}  processed=${m.st.processed}  <- fresh`);

console.log("--- C. new: network error mid-run ---");
const e = makeModel({ radixCallsOnOpenChangeOnPropChange: false });
e.applyProp(true);
const r = await e.runSend(2);
console.log(`  returned=${r} phase=${e.st.phase} processed=${e.st.processed} error="${e.st.error}"`);
console.log(`  ${e.st.phase === "done" && e.st.processed > 0 ? "PASS: progress preserved, not stranded" : "FAIL"}`);

console.log("--- D. new: double click on Continue ---");
const d = makeModel({ radixCallsOnOpenChangeOnPropChange: false });
d.applyProp(true);
const [a, b] = await Promise.all([d.runSend(99), d.runSend(99)]);
console.log(`  first=${a} second=${b} processed=${d.st.processed} (expect 50, second IGNORED)`);
console.log(`  ${d.st.processed === 50 ? "PASS: single run" : "FAIL: duplicate run"}`);

console.log("--- E. Esc during send ---");
const f = makeModel({ radixCallsOnOpenChangeOnPropChange: false });
f.applyProp(true);
const p = f.runSend(2);
console.log(`  close() during sending -> ${f.close()}`);
await p;
console.log(`  ${f.st.phase === "done" ? "PASS: could not abandon mid-run" : "FAIL"}`);
EOF
