// Mirrors the server's queueing + cursor, now using localeCompare on both sides.
const SIZE = 10, DELAY = 900;
let seq = 0;
const mid = (i) => `m${String(i).padStart(4,"0")}-${(i*7919%100000).toString(16)}`;

function makeServer(members) {
  return function send({ after_member_id }) {
    const incomplete = members
      .filter(m => m.status === "incomplete")
      .sort((a,b) => a.member_id.localeCompare(b.member_id));
    if (!incomplete.length) return { error: "All assigned members have completed their contribution." };
    const cursor = String(after_member_id ?? "");
    const startIndex = cursor
      ? incomplete.filter(r => r.member_id.localeCompare(cursor) <= 0).length
      : 0;
    const batch = incomplete.slice(startIndex, startIndex + SIZE);
    const results = batch.map(r => ({
      member_id: r.member_id, name: r.name,
      status: r.email ? "sent" : "skipped",       // invalid treated like missing
    }));
    const sent = results.filter(r=>r.status==="sent").length;
    const failed = 0;
    const skipped = results.filter(r=>r.status==="skipped").length;
    const total = incomplete.length;
    const last = batch[batch.length-1];
    const nextCursor = last?.member_id ?? cursor;
    const remainingAfter = total - incomplete.filter(r => r.member_id.localeCompare(nextCursor) <= 0).length;
    return { results, stats:{sent,failed,skipped,processed:results.length,total}, cursor:nextCursor, hasMore: remainingAfter>0 };
  };
}

async function run(members, { completeMidRun = null } = {}) {
  const send = makeServer(members);
  const contacted = new Map(); let cursor="", n=0, guard=0;
  const totals = {sent:0,failed:0,skipped:0,processed:0};
  for(;;) {
    if (++guard > 200) throw new Error("runaway loop");
    if (completeMidRun) completeMidRun(n);
    const r = send({after_member_id: cursor});
    if (r.error) return { error: r.error };
    for (const x of r.results) {
      if (contacted.has(x.member_id)) return { DOUBLE_SEND: x.name, after: n };
      contacted.set(x.member_id, x.name);
    }
    totals.sent+=r.stats.sent; totals.failed+=r.stats.failed;
    totals.skipped+=r.stats.skipped; totals.processed+=r.stats.processed;
    if (!r.hasMore) break;
    cursor = r.cursor; n++;
    await new Promise(r=>setTimeout(r,1));
  }
  return { contacted, totals };
}

// ---- acceptance scenario from the spec: 500 assigned, 200 completed, 10 no email
const members = Array.from({length:500}, (_,i) => ({
  member_id: mid(i), name: `Member ${i}`,
  status: i < 200 ? "completed" : "incomplete",
  email: (i>=200 && i<210) ? null : `m${i}@example.com`,
}));
const expectedIncomplete = 300, expectedSent = 290, expectedSkipped = 10;
const a = await run(members);
const completedTouched = [...a.contacted.keys()].filter(id => members.find(m=>m.member_id===id).status==="completed");
console.log(`SCENARIO 1: 500 assigned / 200 completed / 10 missing email`);
console.log(`  processed=${a.totals.processed} (expect ${expectedIncomplete}) sent=${a.totals.sent} (expect ${expectedSent}) skipped=${a.totals.skipped} (expect ${expectedSkipped})`);
console.log(`  completed members contacted: ${completedTouched.length} (expect 0)`);
console.log(`  ${a.totals.processed===expectedIncomplete && a.totals.sent===expectedSent && a.totals.skipped===expectedSkipped && completedTouched.length===0 ? "PASS" : "FAIL"}`);

// ---- regression: member completes mid-run (queue shrinks after batch 2)
const m2 = Array.from({length:50}, (_,i)=>({ member_id: mid(i), name:`M${i}`, status:"incomplete", email:`m${i}@e.com` }));
const victim = m2[25].member_id;
const b = await run(m2, { completeMidRun: (n) => { if (n===2) m2.find(x=>x.member_id===victim).status="completed"; } });
console.log(`\nSCENARIO 2: a member completes after batch 2`);
console.log(`  contacted=${b.contacted.size} of 50 (expect 49 — the completed one is skipped)`);
console.log(`  ${b.contacted.size===49 && !b.contacted.has(victim) ? "PASS: nobody skipped by mistake, nobody mailed twice" : "FAIL"}`);

// ---- empty / all-complete
const m3 = Array.from({length:10}, (_,i)=>({ member_id: mid(i), name:`M${i}`, status:"completed", email:`m${i}@e.com` }));
const c = await run(m3);
console.log(`\nSCENARIO 3: all complete`);
console.log(`  ${c.error ? "PASS: "+c.error : "FAIL: attempted a run"}`);

// ---- all missing email
const m4 = Array.from({length:15}, (_,i)=>({ member_id: mid(i), name:`M${i}`, status:"incomplete", email:null }));
const d = await run(m4);
console.log(`\nSCENARIO 4: nobody has an email`);
console.log(`  processed=${d.totals.processed} sent=${d.totals.sent} skipped=${d.totals.skipped}`);
console.log(`  ${d.totals.sent===0 && d.totals.skipped===15 ? "PASS: nothing sent, everyone skipped" : "FAIL"}`);
EOF
