export async function getAssignableMembers(
  eventId: string,
  { search = "", limit = 200 }: { search?: string; limit?: number } = {}
) {
  const supabase = await createClient();

  const { data: assigned } = await supabase
    .from("event_members")
    .select("member_id")
    .eq("event_id", eventId);

  const assignedIds = (assigned ?? []).map((row) => row.member_id as string);

  let query = supabase
    .from("members")
    .select("id, member_id, full_name, phone, email, status")
    .is("deleted_at", null)
    .order("full_name", { ascending: true })
    .limit(limit);

  if (search) {
    query = query.or(
      `full_name.ilike.%${search}%,member_id.ilike.%${search}%,phone.ilike.%${search}%`
    );
  }

  const { data, error } = await query;
  if (error) return [];

  const excluded = new Set(assignedIds);
  return ((data ?? []) as Member[])
    .filter((member) => !excluded.has(member.id))
    .map((member) => ({
      id: member.id,
      member_code: member.member_id,
      full_name: member.full_name,
      phone: member.phone,
      email: member.email,
    }));
}

export async function getAllAnnouncements({
